/**
 * Action 4 Prompt Module for tx-3-imp-1 Agent
 * 
 * Contract: tx_3_imp_1
 * Title: 報告漏れ特定から催促送信までの自動実行
 * 
 * Action 4: 送信結果をログに記録する
 * 
 * This module generates prompts for logging the results of automated
 * reminder email and chat message sending operations.
 */

export const ACTION_04_PROMPT_VERSION = "1.0.0";

export interface PromptContext {
  sendResults: SendResult[];
  timestamp: string;
  agentId: string;
}

export interface SendResult {
  targetMemberId: string;
  targetMemberName: string;
  communicationChannel: "email" | "chat";
  messageId: string;
  sentAt: string;
  status: "success" | "failed" | "pending";
  errorMessage?: string;
  retryCount: number;
}

export interface LogEntry {
  logId: string;
  timestamp: string;
  agentId: string;
  actionType: "send_result_logging";
  totalAttempts: number;
  successCount: number;
  failureCount: number;
  pendingCount: number;
  details: SendResult[];
  summary: string;
}

export function buildAction04Prompt(context: PromptContext): string {
  const { sendResults, timestamp, agentId } = context;

  const successCount = sendResults.filter((r) => r.status === "success").length;
  const failureCount = sendResults.filter((r) => r.status === "failed").length;
  const pendingCount = sendResults.filter((r) => r.status === "pending").length;
  const totalCount = sendResults.length;

  const resultDetails = sendResults
    .map((result) => {
      const channelLabel =
        result.communicationChannel === "email" ? "Email" : "Chat";
      const statusLabel =
        result.status === "success"
          ? "✓ Success"
          : result.status === "failed"
            ? "✗ Failed"
            : "⏳ Pending";

      let detail = `[${statusLabel}] ${result.targetMemberName} (ID: ${result.targetMemberId}) via ${channelLabel}`;
      detail += `\n  Message ID: ${result.messageId}`;
      detail += `\n  Sent At: ${result.sentAt}`;
      detail += `\n  Retry Count: ${result.retryCount}`;

      if (result.errorMessage) {
        detail += `\n  Error: ${result.errorMessage}`;
      }

      return detail;
    })
    .join("\n\n");

  const summaryLine =
    `Total: ${totalCount} | Success: ${successCount} | Failed: ${failureCount} | Pending: ${pendingCount}`;

  const prompt = `You are a logging and record-keeping assistant for the automated reminder notification system.

Your task is to record and summarize the results of the reminder sending operations that were just executed.

## Sending Operation Results

**Timestamp:** ${timestamp}
**Agent ID:** ${agentId}

### Summary
${summaryLine}

### Detailed Results
${resultDetails}

## Your Task

1. **Validate the results**: Ensure all send attempts have been properly recorded with their status and timestamps.

2. **Generate a structured log entry** that includes:
   - Unique log ID (format: LOG_${Date.now()}_${Math.random().toString(36).substr(2, 9)})
   - Complete timestamp
   - Agent ID
   - Action type: "send_result_logging"
   - Count breakdown (total, success, failure, pending)
   - Full details of each send result
   - A concise summary statement

3. **Identify any issues**:
   - Flag any failed sends that may require manual intervention
   - Note any pending sends that exceeded expected timeout
   - Highlight retry patterns that suggest systematic problems

4. **Generate a summary statement** that:
   - Confirms the overall operation status
   - Highlights any critical failures
   - Recommends next steps if needed

## Output Format

Provide your response as a JSON object with the following structure:
{
  "logId": "LOG_...",
  "timestamp": "${timestamp}",
  "agentId": "${agentId}",
  "actionType": "send_result_logging",
  "totalAttempts": ${totalCount},
  "successCount": ${successCount},
  "failureCount": ${failureCount},
  "pendingCount": ${pendingCount},
  "details": [
    {
      "targetMemberId": "...",
      "targetMemberName": "...",
      "communicationChannel": "email|chat",
      "messageId": "...",
      "sentAt": "...",
      "status": "success|failed|pending",
      "errorMessage": "...",
      "retryCount": 0
    }
  ],
  "summary": "...",
  "issuesIdentified": [
    {
      "type": "failed_send|pending_timeout|retry_pattern",
      "targetMemberId": "...",
      "description": "...",
      "recommendedAction": "..."
    }
  ]
}

Ensure all timestamps are in ISO 8601 format and all IDs are properly formatted.`;

  return prompt;
}
